import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S04/S04E08.html","title":"S04E08 The One with Chandler in a Box","lang":"zh-CN","frontmatter":{"title":"S04E08 The One with Chandler in a Box","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":81},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":34.09,"words":10226},"filePathRelative":"语言/英语/Friends老友记/S04/S04E08.md"}`),l={name:`S04E08.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-chandler-in-a-box" tabindex="-1"><a class="header-anchor" href="#the-one-with-chandler-in-a-box"><span>The One with Chandler in a Box</span></a></h1><blockquote><p><em>钱德勒在盒子里的那个</em></p></blockquote><p>The One With Chandler in a Box</p><blockquote><p>钱德勒在盒子里的那个</p></blockquote><p><strong>Written by: Michael Borkow</strong></p><blockquote><p>作者：Michael Borkow</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Joey is sitting at the counter reading a magazine as the phone rings.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊家，乔伊坐在柜台边看杂志，电话铃响了。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S04/S04E08/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[3]||=i(` (answering phone) Hello.`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`（接电话）你好。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/002.mp3`}),c[5]||=t(` <strong>Chandler Bing:</strong> (on phone) Hey, it’s me. I know you can’t stand to be in the same room as me, so I just thought I’d try and apologize over the phone. All I… (Joey hangs up the phone in disgust.)<blockquote><p>（在电话里）嘿，是我。我知道你不能忍受和我在同一个房间，所以我想我应该试着在电话里道歉。所有我…（乔伊厌恶地挂断了电话。）</p></blockquote><p><em>(Pause)</em></p><blockquote><p><em>（停顿）</em></p></blockquote><p><em>(The phone rings again.)</em></p><blockquote><p><em>（电话又响了。）</em></p></blockquote>`,8),r(p,{src:`/audio/friends/S04/S04E08/003.mp3`}),c[6]||=i(),c[7]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[8]||=i(` (answering phone) Hello.`,-1),c[9]||=a(`blockquote`,null,[a(`p`,null,`（接电话）你好。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/004.mp3`}),c[10]||=t(` <strong>Chandler Bing:</strong> Look I never should have kissed your girlfriend, but I’m… (Joey hangs up the phone again.)<blockquote><p>听着，我不该吻你的女朋友，但我…（乔伊又挂断了电话。）</p></blockquote><p><em>(Pause)</em></p><blockquote><p><em>（停顿）</em></p></blockquote><p><em>(The phone rings yet again.)</em></p><blockquote><p><em>（电话又响了。）</em></p></blockquote>`,8),r(p,{src:`/audio/friends/S04/S04E08/005.mp3`}),c[11]||=i(),c[12]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[13]||=i(` (answering phone) Stop callin’!!`,-1),c[14]||=a(`blockquote`,null,[a(`p`,null,`（接电话）别打电话了！！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/006.mp3`}),c[15]||=i(),c[16]||=a(`strong`,null,`Voice:`,-1),c[17]||=i(` (on phone) Hey! Hey! Hey! This is 92.3, WXRK, K-Rock for our $1,000 daily challenge.`,-1),c[18]||=a(`blockquote`,null,[a(`p`,null,`（在电话里）嘿！嘿嘿这是92.3，WXRK，K-Rock，我们每天1000美元的挑战。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/007.mp3`}),c[19]||=i(),c[20]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[21]||=i(` All right!`,-1),c[22]||=a(`blockquote`,null,[a(`p`,null,`好吧！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/008.mp3`}),c[23]||=t(` <strong>Voice:</strong> What is the name of your roommate who is very, very sorry and would do anything… (Joey realizes it’s Chandler and hangs up the phone in anger.)<blockquote><p>你的室友叫什么名字？他非常非常抱歉，什么都愿意做…（乔伊意识到是钱德勒，生气地挂断了电话。）</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, everyone but Joey and Chandler are there getting ready for Thanksgiving.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，除了乔伊和钱德勒，所有人都在为感恩节做准备。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S04/S04E08/009.mp3`}),c[24]||=i(),c[25]||=a(`strong`,null,`Chandler Bing:`,-1),c[26]||=i(` (entering) Aww, turkey! Aww, giving thanks! Aww!`,-1),c[27]||=a(`blockquote`,null,[a(`p`,null,`（进来）啊，土耳其！啊，谢谢你！啊！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/010.mp3`}),c[28]||=i(),c[29]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[30]||=i(` Look everyone, it’s the spirit of Thanksgiving!`,-1),c[31]||=a(`blockquote`,null,[a(`p`,null,`大家看，这是感恩节的精神！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/011.mp3`}),c[32]||=i(),c[33]||=a(`strong`,null,`Rachel Green:`,-1),c[34]||=i(` So are things with you and Joey any better?`,-1),c[35]||=a(`blockquote`,null,[a(`p`,null,`你和乔伊的情况好点了吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/012.mp3`}),c[36]||=i(),c[37]||=a(`strong`,null,`Chandler Bing:`,-1),c[38]||=i(` They couldn’t be worse. I spent eight hours calling him last night, just trying to get him to talk to me.`,-1),c[39]||=a(`blockquote`,null,[a(`p`,null,`再糟糕不过了。我昨晚花了八个小时给他打电话，只是想让他跟我说话。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/013.mp3`}),c[40]||=i(),c[41]||=a(`strong`,null,`Rachel Green:`,-1),c[42]||=i(` Oh wow, eight hours? So you could probably really use one of those plug-in telephone headsets huh?`,-1),c[43]||=a(`blockquote`,null,[a(`p`,null,`哦，哇，八个小时？所以你可能真的可以用一个插入式电话耳机？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/014.mp3`}),c[44]||=i(),c[45]||=a(`strong`,null,`Ross Geller:`,-1),c[46]||=i(` Should we all expect Christmas gifts that can be stolen from your office?`,-1),c[47]||=a(`blockquote`,null,[a(`p`,null,`我们都应该期待圣诞礼物能从你的办公室偷走吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/015.mp3`}),c[48]||=i(),c[49]||=a(`strong`,null,`Rachel Green:`,-1),c[50]||=i(` You shouldn’t.`,-1),c[51]||=a(`blockquote`,null,[a(`p`,null,`你不应该。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/016.mp3`}),c[52]||=i(),c[53]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[54]||=i(` Speaking of Christmas, umm since Monica and I are starting a new business and have like no money, umm, this year maybe we could do secret Santa, and then we each only buy one gift. And-and there’s the added mystery of who gets who.`,-1),c[55]||=a(`blockquote`,null,[a(`p`,null,`说到圣诞节，嗯，因为莫妮卡和我要开始一项新的生意，而且没有钱，嗯，今年也许我们可以做秘密圣诞老人，然后我们每人只买一件礼物。还有一个额外的谜团是谁得到谁。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/017.mp3`}),c[56]||=i(),c[57]||=a(`strong`,null,`Ross Geller:`,-1),c[58]||=i(` Who gets whom. (They all look at him.) I don’t know why I do that.`,-1),c[59]||=a(`blockquote`,null,[a(`p`,null,`谁得到谁。（他们都看着他。）我不知道我为什么这么做。`)],-1),c[60]||=a(`p`,null,`[Cut to later, the gang, minus Joey, is watching the Thanksgiving Day parade.]`,-1),c[61]||=a(`blockquote`,null,[a(`p`,null,`[稍后，这帮人，除了乔伊，正在观看感恩节游行。]`)],-1),r(p,{src:`/audio/friends/S04/S04E08/018.mp3`}),c[62]||=i(),c[63]||=a(`strong`,null,`Rachel Green:`,-1),c[64]||=i(` Well, I’m gonna take a nap, turkey makes me sleepy.`,-1),c[65]||=a(`blockquote`,null,[a(`p`,null,`好吧，我要小睡一会儿，火鸡让我昏昏欲睡。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/019.mp3`}),c[66]||=i(),c[67]||=a(`strong`,null,`Monica Geller:`,-1),c[68]||=i(` We haven’t eaten yet!`,-1),c[69]||=a(`blockquote`,null,[a(`p`,null,`我们还没吃呢！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/020.mp3`}),c[70]||=i(),c[71]||=a(`strong`,null,`Rachel Green:`,-1),c[72]||=i(` I know, but all that work you’re doing to get it ready, I just… (goes into her bedroom.)`,-1),c[73]||=a(`blockquote`,null,[a(`p`,null,`我知道，但你为准备而做的所有工作，我只是…（走进她的卧室。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/021.mp3`}),c[74]||=i(),c[75]||=a(`strong`,null,`Chandler Bing:`,-1),c[76]||=i(` Hey, by any chance did either of pick uh Rachel for your secret Santa, ‘cause I wanna trade for her.`,-1),c[77]||=a(`blockquote`,null,[a(`p`,null,`嘿，你们俩谁选了瑞秋做你们的秘密圣诞老人，因为我想和她交易。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/022.mp3`}),c[78]||=i(),c[79]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[80]||=i(` I picked her! Oh thank God you want her! Ooh!`,-1),c[81]||=a(`blockquote`,null,[a(`p`,null,`我选了她！感谢上帝你想要她！哦！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/023.mp3`}),c[82]||=i(),c[83]||=a(`strong`,null,`Chandler Bing:`,-1),c[84]||=i(` Wow! Why do you want to get rid of her so badly?`,-1),c[85]||=a(`blockquote`,null,[a(`p`,null,`哇！你为什么这么想摆脱她？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/024.mp3`}),c[86]||=i(),c[87]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[88]||=i(` Because she exchanges every gift she ever gets, it’s like impossible to get her something she likes. Come on, let’s trade!`,-1),c[89]||=a(`blockquote`,null,[a(`p`,null,`因为她会交换她收到的每一件礼物，所以她不可能得到她喜欢的东西。来吧，我们交易吧！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/025.mp3`}),c[90]||=i(),c[91]||=a(`strong`,null,`Chandler Bing:`,-1),c[92]||=i(` Oh that’s not true! That’s not true! I got her that backpack and she loved it! I remember how much she was crying the day when that big dog ran off with it… (notices the look on Monica and Phoebe’s faces.) Oh, there was no big dog. All right this sucks! I already got her this briefcase, and I had R.G. put on it… (Phoebe looks confused.) Her initials…`,-1),c[93]||=a(`blockquote`,null,[a(`p`,null,`哦，那不是真的！那不是真的！我给她买了那个背包，她很喜欢！我记得那天那只大狗带着它跑的时候她哭得多厉害…（注意到莫妮卡和菲比脸上的表情。）哦，没有大狗。好吧，这太糟糕了！我已经给她拿了这个公文包，我让R.G.放在上面…（菲比看起来很困惑。）她的名字缩写…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/026.mp3`}),c[94]||=i(),c[95]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[96]||=i(` Ohh.`,-1),c[97]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/027.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`Monica Geller:`,-1),c[100]||=i(` Well, maybe you could give to somebody else. Ooh, like Ross Geller.`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`嗯，也许你可以给别人。哦，就像罗斯·盖勒。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/028.mp3`}),c[102]||=i(),c[103]||=a(`strong`,null,`Chandler Bing:`,-1),c[104]||=i(` Op, y'know what though, it’s kind’ve a girlie briefcase.`,-1),c[105]||=a(`blockquote`,null,[a(`p`,null,`哦，你知道吗，我有一个女孩子的公文包。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/029.mp3`}),c[106]||=i(),c[107]||=a(`strong`,null,`Monica Geller:`,-1),c[108]||=i(` Who cares? He works in a museum!`,-1),c[109]||=a(`blockquote`,null,[a(`p`,null,`谁在乎？他在博物馆工作！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/030.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`Chandler Bing:`,-1),c[112]||=i(` Hey, what time is it? The big game is about to start!`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`嘿，现在几点了？大赛就要开始了！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/031.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[116]||=i(` You don’t have to do that, Ross and Joey aren’t here, you can watch the parade if you want.`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`你不必这么做，罗斯和乔伊不在，如果你愿意，你可以看游行。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/032.mp3`}),c[118]||=i(),c[119]||=a(`strong`,null,`Chandler Bing:`,-1),c[120]||=i(` Thanks.`,-1),c[121]||=a(`blockquote`,null,[a(`p`,null,`谢谢。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/033.mp3`}),c[122]||=i(),c[123]||=a(`strong`,null,`Monica Geller:`,-1),c[124]||=i(` What is wrong with this freezer?! (She jabs her arm into the freezer and a piece of ice flies into her eye.) Ow! Ow!!`,-1),c[125]||=a(`blockquote`,null,[a(`p`,null,`这冰箱怎么了？！（她把手伸进冰箱，一块冰飞进了她的眼睛。）哇！噢`)],-1),r(p,{src:`/audio/friends/S04/S04E08/034.mp3`}),c[126]||=i(),c[127]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[128]||=i(` God, what happened?!`,-1),c[129]||=a(`blockquote`,null,[a(`p`,null,`天啊，发生什么事了？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/035.mp3`}),c[130]||=i(),c[131]||=a(`strong`,null,`Monica Geller:`,-1),c[132]||=i(` Oh my God, ice just got in my eye!`,-1),c[133]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊，冰刚进入我的眼睛！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/036.mp3`}),c[134]||=i(),c[135]||=a(`strong`,null,`Rachel Green:`,-1),c[136]||=i(` (standing in her doorway) People are trying to sleep in here!`,-1),c[137]||=a(`blockquote`,null,[a(`p`,null,`（站在门口）人们都想在这里睡觉！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/037.mp3`}),c[138]||=i(),c[139]||=a(`strong`,null,`Chandler Bing:`,-1),c[140]||=i(` Monica got ice in her eye, and it hurts.`,-1),c[141]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡的眼睛里有冰，而且很疼。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/038.mp3`}),c[142]||=i(),c[143]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[144]||=i(` Open it up, let me see.`,-1),c[145]||=a(`blockquote`,null,[a(`p`,null,`打开，让我看看。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/039.mp3`}),c[146]||=i(),c[147]||=a(`strong`,null,`Monica Geller:`,-1),c[148]||=i(` Oh, y’know what, I can’t, it really kills.`,-1),c[149]||=a(`blockquote`,null,[a(`p`,null,`哦，你知道吗，我不能，这真的很要命。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/040.mp3`}),c[150]||=i(),c[151]||=a(`strong`,null,`Chandler Bing:`,-1),c[152]||=i(` Well maybe you should put some ice on it.`,-1),c[153]||=a(`blockquote`,null,[a(`p`,null,`也许你应该在上面加点冰。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/041.mp3`}),c[154]||=i(),c[155]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[156]||=i(` Ooh, God it looks bad.`,-1),c[157]||=a(`blockquote`,null,[a(`p`,null,`哦，天啊，看起来糟透了。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/042.mp3`}),c[158]||=i(),c[159]||=a(`strong`,null,`Rachel Green:`,-1),c[160]||=i(` Honey, maybe we should take you to a doctor.`,-1),c[161]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，也许我们应该带你去看医生。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/043.mp3`}),c[162]||=i(),c[163]||=a(`strong`,null,`Monica Geller:`,-1),c[164]||=i(` No, my eye doctor is Richard! I can’t go to him when I don’t have a boyfriend!`,-1),c[165]||=a(`blockquote`,null,[a(`p`,null,`不，我的眼科医生是理查德！我没有男朋友就不能去找他！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/044.mp3`}),c[166]||=i(),c[167]||=a(`strong`,null,`Chandler Bing:`,-1),c[168]||=i(` He’s really picky about his patients.`,-1),c[169]||=a(`blockquote`,null,[a(`p`,null,`他对病人很挑剔。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/045.mp3`}),c[170]||=i(),c[171]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[172]||=i(` Honey, you’ve got to go. What’s his office number?`,-1),c[173]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，你得走了。他的办公室号码是多少？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/046.mp3`}),c[174]||=i(),c[175]||=a(`strong`,null,`Monica Geller:`,-1),c[176]||=i(` Like I remember his office number! (Pause) Speed dial 7.`,-1),c[177]||=a(`blockquote`,null,[a(`p`,null,`就像我记得他的办公室号码一样！（暂停）快速拨号7。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/047.mp3`}),c[178]||=i(),c[179]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[180]||=i(` (on phone) Hi! Yeah, I’m calling on behalf of Monica Geller’s eye, and is um, is Richard Burke in today. (Listens) (to Monica) He’s out of town, but does she want to see the on-call doctor?`,-1),c[181]||=a(`blockquote`,null,[a(`p`,null,`（打电话）嗨！是的，我是代表Monica Geller的眼睛打电话的，Richard Burke今天在吗。（听）（莫妮卡）他不在城里，但她想去看随叫随到的医生吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/048.mp3`}),c[182]||=i(),c[183]||=a(`strong`,null,`Monica Geller:`,-1),c[184]||=i(` Yes!!`,-1),c[185]||=a(`blockquote`,null,[a(`p`,null,`是的！！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/049.mp3`}),c[186]||=i(),c[187]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[188]||=i(` Yes! She’s very excited about that.`,-1),c[189]||=a(`blockquote`,null,[a(`p`,null,`是的！她对此非常兴奋。`)],-1),c[190]||=a(`p`,null,`[Cut to later, Phoebe is adding butter to something and Ross is watching.]`,-1),c[191]||=a(`blockquote`,null,[a(`p`,null,`[切到稍后，菲比正在往东西上加黄油，罗斯在看。]`)],-1),r(p,{src:`/audio/friends/S04/S04E08/050.mp3`}),c[192]||=i(),c[193]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[194]||=i(` This is so cool, ‘til Monica gets back, it’s like I’m head chef and I get to make all the decisions. (She looks at the remaining butter, and then decides to add it to the dish.)`,-1),c[195]||=a(`blockquote`,null,[a(`p`,null,`这太酷了，在莫妮卡回来之前，就好像我是主厨，我要做所有的决定。（她看了看剩下的黄油，然后决定把它加到盘子里。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/051.mp3`}),c[196]||=i(),c[197]||=a(`strong`,null,`Ross Geller:`,-1),c[198]||=i(` Hey-hey, I thought she told you to follow the recipe exactly!`,-1),c[199]||=a(`blockquote`,null,[a(`p`,null,`嘿，嘿，我以为她让你严格按照食谱做的！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/052.mp3`}),c[200]||=i(),c[201]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[202]||=i(` Okay, get out of my kitchen!`,-1),c[203]||=a(`blockquote`,null,[a(`p`,null,`好的，从我的厨房里出来！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/053.mp3`}),c[204]||=i(),c[205]||=a(`strong`,null,`Chandler Bing:`,-1),c[206]||=i(` (entering) All right! Okay! I think I am making some progress with Joey, when I went into the apartment he went straight into his bedroom but he only slammed the door once! (Ross is pleased.) I mean yeah, he gave me the finger while doing it.`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`（进来）好吧！可以我想我正在和乔伊取得一些进展，当我走进公寓时，他径直走进他的卧室，但他只砰地关了一次门！（罗斯很高兴）我是说是的，他在做的时候给了我一个手指。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/054.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[210]||=i(` All right I… I gotta call my mom and ask her a left handed cooking question.`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`好吧，我……我得打电话给我妈妈，问她一个关于烹饪的左撇子问题。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/055.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Ross Geller:`,-1),c[214]||=i(` So listen ah, I picked Monica for secret Santa, but I’m already getting her something for Chanukah, I was wondering if you wanna switch.`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`听着，我选莫妮卡做秘密圣诞老人，但我已经给她买了些钱，我想知道你是否想换一个。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/056.mp3`}),c[216]||=i(),c[217]||=a(`strong`,null,`Chandler Bing:`,-1),c[218]||=i(` Oh y’know what, I was already trying to trade for ah, well, you.`,-1),c[219]||=a(`blockquote`,null,[a(`p`,null,`哦，你知道吗，我已经试着用你来交易了。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/057.mp3`}),c[220]||=i(),c[221]||=a(`strong`,null,`Ross Geller:`,-1),c[222]||=i(` Really?! Wow! That’s-that’s so nice, what are you gonna get me?`,-1),c[223]||=a(`blockquote`,null,[a(`p`,null,`真的吗？！哇！太好了，你要给我买什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/058.mp3`}),c[224]||=i(),c[225]||=a(`strong`,null,`Chandler Bing:`,-1),c[226]||=i(` I don’t know R.G., I was thinking something girlie for your office.`,-1),c[227]||=a(`blockquote`,null,[a(`p`,null,`我不知道R.G.，我在为你的办公室考虑一些女孩的东西。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/059.mp3`}),c[228]||=i(),c[229]||=a(`strong`,null,`Ross Geller:`,-1),c[230]||=i(` Yeah, well maybe Phoebe will switch with me.`,-1),c[231]||=a(`blockquote`,null,[a(`p`,null,`是啊，也许菲比会跟我换。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/060.mp3`}),c[232]||=i(),c[233]||=a(`strong`,null,`Chandler Bing:`,-1),c[234]||=i(` Oh no-no-no, you don’t want to do that, then you’re gonna get stuck with Rachel and she exchanges every gift she ever gets.`,-1),c[235]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，你不想那样做，那么你会被瑞秋缠住，她会交换她收到的每一件礼物。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/061.mp3`}),c[236]||=i(),c[237]||=a(`strong`,null,`Ross Geller:`,-1),c[238]||=i(` Oh, that’s not true! I’ve got her lots of stuff she never took back.`,-1),c[239]||=a(`blockquote`,null,[a(`p`,null,`哦，那不是真的！我给她买了很多东西，她从没拿过。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/062.mp3`}),c[240]||=i(),c[241]||=a(`strong`,null,`Chandler Bing:`,-1),c[242]||=i(` Like?`,-1),c[243]||=a(`blockquote`,null,[a(`p`,null,`比如说？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/063.mp3`}),c[244]||=i(),c[245]||=a(`strong`,null,`Ross Geller:`,-1),c[246]||=i(` Like uh, that gold necklace I got her last year.`,-1),c[247]||=a(`blockquote`,null,[a(`p`,null,`就像我去年给她的那条金项链。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/064.mp3`}),c[248]||=i(),c[249]||=a(`strong`,null,`Chandler Bing:`,-1),c[250]||=i(` When was the last time you saw her wear it?`,-1),c[251]||=a(`blockquote`,null,[a(`p`,null,`你最后一次看到她戴它是什么时候？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/065.mp3`}),c[252]||=i(),c[253]||=a(`strong`,null,`Ross Geller:`,-1),c[254]||=i(` Well, she wore it all Christmas day, and then uh…`,-1),c[255]||=a(`blockquote`,null,[a(`p`,null,`嗯，她整个圣诞节都穿着它，然后呢…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/066.mp3`}),c[256]||=i(),c[257]||=a(`strong`,null,`Chandler Bing:`,-1),c[258]||=i(` Big dog?`,-1),c[259]||=a(`blockquote`,null,[a(`p`,null,`大狗？`)],-1),c[260]||=a(`hr`,null,null,-1),c[261]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Joey is repacking the furniture into boxes to return it.`)],-1),c[262]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊家，乔伊正在把家具重新包装成盒子，以便归还。`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/067.mp3`}),c[263]||=i(),c[264]||=a(`strong`,null,`Ross Geller:`,-1),c[265]||=i(` (entering) Hey!`,-1),c[266]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/068.mp3`}),c[267]||=i(),c[268]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[269]||=i(` Hey!`,-1),c[270]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/069.mp3`}),c[271]||=i(),c[272]||=a(`strong`,null,`Ross Geller:`,-1),c[273]||=i(` What are you doing?`,-1),c[274]||=a(`blockquote`,null,[a(`p`,null,`你在干什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/070.mp3`}),c[275]||=i(),c[276]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[277]||=i(` I’m sending back all this stuff that Chandler bought out of guilt.`,-1),c[278]||=a(`blockquote`,null,[a(`p`,null,`我要把钱德勒出于内疚买的所有东西都寄回去。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/071.mp3`}),c[279]||=i(),c[280]||=a(`strong`,null,`Ross Geller:`,-1),c[281]||=i(` Everything? Even the TV?`,-1),c[282]||=a(`blockquote`,null,[a(`p`,null,`一切都好吗？甚至是电视？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/072.mp3`}),c[283]||=i(),c[284]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[285]||=i(` No! I’m putting that in my room.`,-1),c[286]||=a(`blockquote`,null,[a(`p`,null,`不！我把它放在我的房间里。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/073.mp3`}),c[287]||=i(),c[288]||=a(`strong`,null,`Ross Geller:`,-1),c[289]||=i(` Listen, Joey, I know what he did was wrong but don’t you think you could at least hear the guy out?`,-1),c[290]||=a(`blockquote`,null,[a(`p`,null,`听着，乔伊，我知道他做错了，但你不觉得你至少能听到他说出来吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/074.mp3`}),c[291]||=i(),c[292]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[293]||=i(` Back when you and Rachel were together, if Chandler had kissed her, would you hear him out?`,-1),c[294]||=a(`blockquote`,null,[a(`p`,null,`当你和瑞秋在一起的时候，如果钱德勒吻了她，你会听他说完吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/075.mp3`}),c[295]||=i(),c[296]||=a(`strong`,null,`Ross Geller:`,-1),c[297]||=i(` That’s a good point. So uh, how long are you gonna punish him?`,-1),c[298]||=a(`blockquote`,null,[a(`p`,null,`这是一个很好的观点。你打算惩罚他多久？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/076.mp3`}),c[299]||=i(),c[300]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[301]||=i(` Five years.`,-1),c[302]||=a(`blockquote`,null,[a(`p`,null,`五年。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/077.mp3`}),c[303]||=i(),c[304]||=a(`strong`,null,`Ross Geller:`,-1),c[305]||=i(` You’ve sentenced him?!`,-1),c[306]||=a(`blockquote`,null,[a(`p`,null,`你判刑了？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/078.mp3`}),c[307]||=i(),c[308]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[309]||=i(` Hey! Don’t do the crime if you can’t do the time.`,-1),c[310]||=a(`blockquote`,null,[a(`p`,null,`嘿！如果你没有时间，就不要犯罪。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/079.mp3`}),c[311]||=i(),c[312]||=a(`strong`,null,`Ross Geller:`,-1),c[313]||=i(` Joey, the guy’s your best friend.`,-1),c[314]||=a(`blockquote`,null,[a(`p`,null,`乔伊，这家伙是你最好的朋友。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/080.mp3`}),c[315]||=i(),c[316]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[317]||=i(` No, was my best friend. Anyway, I don’t know why you’re pushing for him so hard. With him out of the way as my best friend, there’s a spot open.`,-1),c[318]||=a(`blockquote`,null,[a(`p`,null,`不，是我最好的朋友。不管怎么说，我不知道你为什么这么拼命地追求他。他是我最好的朋友，有一个空缺。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/081.mp3`}),c[319]||=i(),c[320]||=a(`strong`,null,`Ross Geller:`,-1),c[321]||=i(` Oh, who? Me?`,-1),c[322]||=a(`blockquote`,null,[a(`p`,null,`哦，谁？我`)],-1),r(p,{src:`/audio/friends/S04/S04E08/082.mp3`}),c[323]||=i(),c[324]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[325]||=i(` Yeah!`,-1),c[326]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/083.mp3`}),c[327]||=i(),c[328]||=a(`strong`,null,`Ross Geller:`,-1),c[329]||=i(` Wow! I’m honored! And y’know what I’m gonna do as my first act as your best friend?`,-1),c[330]||=a(`blockquote`,null,[a(`p`,null,`哇！我很荣幸！你知道我第一次扮演你最好的朋友要做什么吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/084.mp3`}),c[331]||=i(),c[332]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[333]||=i(` What?`,-1),c[334]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/085.mp3`}),c[335]||=i(),c[336]||=a(`strong`,null,`Ross Geller:`,-1),c[337]||=i(` I’m gonna get you to talk to Chandler.`,-1),c[338]||=a(`blockquote`,null,[a(`p`,null,`我会让你和钱德勒谈谈。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/086.mp3`}),c[339]||=i(),c[340]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[341]||=i(` All right. But if you weren’t my best friend.`,-1),c[342]||=a(`blockquote`,null,[a(`p`,null,`好的。但如果你不是我最好的朋友。`)],-1),c[343]||=a(`hr`,null,null,-1),c[344]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Chandler and Kathy are sitting at a table and talking about Joey.`)],-1),c[345]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，钱德勒和凯西坐在桌旁谈论乔伊。`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/087.mp3`}),c[346]||=i(),c[347]||=a(`strong`,null,`Kathy:`,-1),c[348]||=i(` Oh my God, is it really that bad?`,-1),c[349]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，真的有那么糟糕吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/088.mp3`}),c[350]||=i(),c[351]||=a(`strong`,null,`Chandler Bing:`,-1),c[352]||=i(` I walk into a room and he won’t even talk to me, he just mumbles something in Italian. And I know he only knows the bad words.`,-1),c[353]||=a(`blockquote`,null,[a(`p`,null,`我走进一个房间，他甚至不跟我说话，他只是用意大利语咕哝着什么。我知道他只知道坏话。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/089.mp3`}),c[354]||=i(),c[355]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[356]||=i(` (entering) Hey Gunther, have you uh, have you seen Chandler?`,-1),c[357]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，冈瑟，你见过钱德勒吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/090.mp3`}),c[358]||=i(),c[359]||=a(`strong`,null,`Gunther:`,-1),c[360]||=i(` I thought you were Chandler. But umm, one of who is over there.`,-1),c[361]||=a(`blockquote`,null,[a(`p`,null,`我还以为你是钱德勒呢。但是，嗯，有一个人在那边。`)],-1),c[362]||=a(`p`,null,[a(`em`,null,`(Joey turns around and sees them kissing.)`)],-1),c[363]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊转过身，看到他们在接吻。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/091.mp3`}),c[364]||=i(),c[365]||=a(`strong`,null,`Kathy:`,-1),c[366]||=i(` Oh.`,-1),c[367]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/092.mp3`}),c[368]||=i(),c[369]||=a(`strong`,null,`Chandler Bing:`,-1),c[370]||=i(` Hey Joe.`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/093.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[374]||=i(` (Something in Italian.) (Storms out.)`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`（意大利语的。）（冲了出去。）`)],-1),c[376]||=a(`hr`,null,null,-1),c[377]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Dr. Burke’s office, Rachel and Monica are waiting as the doctor arrives.`)],-1),c[378]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`伯克医生的办公室，瑞秋和莫妮卡等着医生到来。`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/094.mp3`}),c[379]||=i(),c[380]||=a(`strong`,null,`Doctor:`,-1),c[381]||=i(` I’ll be right with you. Okay? (to the nurse) Thanks, Wendy.`,-1),c[382]||=a(`blockquote`,null,[a(`p`,null,`我马上就来。可以（对护士）谢谢，温迪。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/095.mp3`}),c[383]||=i(),c[384]||=a(`strong`,null,`Monica Geller:`,-1),c[385]||=i(` Oh my God! How cute is the on-call doctor?`,-1),c[386]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！待命医生有多可爱？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/096.mp3`}),c[387]||=i(),c[388]||=a(`strong`,null,`Rachel Green:`,-1),c[389]||=i(` Ooh, so cute, that I’m thinking about jamming this pen in my eye.`,-1),c[390]||=a(`blockquote`,null,[a(`p`,null,`哦，太可爱了，我想把这支笔塞进我的眼睛里。`)],-1),c[391]||=a(`p`,null,[a(`em`,null,`(The intercom buzzes.)`)],-1),c[392]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（对讲机嗡嗡响。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/097.mp3`}),c[393]||=i(),c[394]||=a(`strong`,null,`Nurse:`,-1),c[395]||=i(` Dr. Burke will see you know.`,-1),c[396]||=a(`blockquote`,null,[a(`p`,null,`伯克医生会来看你的。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/098.mp3`}),c[397]||=i(),c[398]||=a(`strong`,null,`Monica Geller:`,-1),c[399]||=i(` Oh no-no-no, not Dr. Burke. Dr. Burke is out of town. The-the on-call doctor will see me now.`,-1),c[400]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，不是伯克医生。伯克医生不在城里。待命医生现在就来看我。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/099.mp3`}),c[401]||=t(` <strong>Nurse:</strong> Dr. Richard Burke is out of town. Dr. Timothy Burke, his son, will see you now.<blockquote><p>理查德·伯克医生不在城里。他的儿子蒂莫西·伯克医生现在来看你。</p></blockquote><p>Dr. Timothy Burke: Ready?</p><blockquote><p>准备好了吗？</p></blockquote><p><em>(Monica looks at Rachel, who gives her the thumbs up.)</em></p><blockquote><p><em>（莫妮卡看着瑞秋，瑞秋竖起大拇指。）</em></p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Joey is packing as Chandler rushes in.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的，乔伊正在收拾行李，钱德勒冲了进来。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S04/S04E08/100.mp3`}),c[402]||=i(),c[403]||=a(`strong`,null,`Chandler Bing:`,-1),c[404]||=i(` Hey! I’m sorry! That—(sees that Joey is about to leave) where are you going?`,-1),c[405]||=a(`blockquote`,null,[a(`p`,null,`嘿！我很抱歉！（看到乔伊要走了）你要去哪里？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/101.mp3`}),c[406]||=i(),c[407]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[408]||=i(` My folks.`,-1),c[409]||=a(`blockquote`,null,[a(`p`,null,`我的家人。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/102.mp3`}),c[410]||=i(),c[411]||=a(`strong`,null,`Chandler Bing:`,-1),c[412]||=i(` Oh, uh, when-when are you coming back?`,-1),c[413]||=a(`blockquote`,null,[a(`p`,null,`哦，呃，你什么时候回来？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/103.mp3`}),c[414]||=i(),c[415]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[416]||=i(` I don’t know. I might stay there for a few days while I look for an apartment.`,-1),c[417]||=a(`blockquote`,null,[a(`p`,null,`我不知道。我可能会在那里呆几天，找一套公寓。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/104.mp3`}),c[418]||=i(),c[419]||=a(`strong`,null,`Chandler Bing:`,-1),c[420]||=i(` What?!`,-1),c[421]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/105.mp3`}),c[422]||=i(),c[423]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[424]||=i(` Yeah, y’know at first I thought we could talk about this y’know, work it out, but uh, seeing you two together I don’t think I…`,-1),c[425]||=a(`blockquote`,null,[a(`p`,null,`是的，一开始我想我们可以谈谈这个，你知道，解决它，但是，看到你们两个在一起，我不认为我…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/106.mp3`}),c[426]||=i(),c[427]||=a(`strong`,null,`Chandler Bing:`,-1),c[428]||=i(` Hey, look, what do you want me to say? Do you want me to say that I’ll stop seeing her?`,-1),c[429]||=a(`blockquote`,null,[a(`p`,null,`嘿，听着，你想让我说什么？你想让我说我不见她了吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/107.mp3`}),c[430]||=i(),c[431]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[432]||=i(` Look, it’s not about her. Okay? But seeing you two together just reminds me of what you did. And I don’t want to live with some one who doesn’t know what it is to be a friend. So, I’ll see ya. (He starts to leave, but Chandler grabs his bag and stops him.)`,-1),c[433]||=a(`blockquote`,null,[a(`p`,null,`听着，这和她无关。可以但看到你们俩在一起让我想起了你们的所作所为。我不想和一个不知道做朋友是什么的人住在一起。那么，再见。（他开始离开，但钱德勒抓起他的包拦住了他。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/108.mp3`}),c[434]||=i(),c[435]||=a(`strong`,null,`Chandler Bing:`,-1),c[436]||=i(` Hey, look, I know what it is to be a friend, I just-I just screwed up!`,-1),c[437]||=a(`blockquote`,null,[a(`p`,null,`嘿，听着，我知道做朋友是什么，我只是，我只是搞砸了！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/109.mp3`}),c[438]||=i(),c[439]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[440]||=i(` Yeah! You did! And that’s why I’m leaving.`,-1),c[441]||=a(`blockquote`,null,[a(`p`,null,`是啊！你做到了！这就是我离开的原因。`)],-1),c[442]||=a(`p`,null,[a(`em`,null,`(The chick and the duck walk into the living room.)`)],-1),c[443]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（小鸡和鸭子走进客厅。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/110.mp3`}),c[444]||=i(),c[445]||=a(`strong`,null,`Chandler Bing:`,-1),c[446]||=i(` All right look, if you’re not gonna stay for me, then at least stay for them! Okay, they have had a very difficult year! What with the robbery and all!`,-1),c[447]||=a(`blockquote`,null,[a(`p`,null,`好吧，听着，如果你不想为我留下来，那么至少要为他们留下来！好吧，他们度过了非常艰难的一年！抢劫和所有的一切！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/111.mp3`}),c[448]||=i(),c[449]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[450]||=i(` When that guy was robbing us, and I was locked in the entertainment unit for like six hours, you know what I was doing in there all that time? I was thinking about how I let you down!`,-1),c[451]||=a(`blockquote`,null,[a(`p`,null,`那家伙抢劫我们的时候，我被锁在娱乐室里六个小时，你知道我一直在那里干什么吗？我在想我是怎么让你失望的！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/112.mp3`}),c[452]||=i(),c[453]||=a(`strong`,null,`Chandler Bing:`,-1),c[454]||=i(` What?`,-1),c[455]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/113.mp3`}),c[456]||=i(),c[457]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[458]||=i(` Yeah! But if would’ve know what kind of friend you were gonna turn out to be, I wouldn’t have worried about it so much! See you around!`,-1),c[459]||=a(`blockquote`,null,[a(`p`,null,`是啊！但如果我知道你会成为什么样的朋友，我就不会这么担心了！回头见！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/114.mp3`}),c[460]||=i(),c[461]||=a(`strong`,null,`Chandler Bing:`,-1),c[462]||=i(` All right, wait! Come on! Just wait one second! There has to be something that I can do! Something! If we still had that entertainment unit I would get in it for six hours and think about how I let you down. (Joey looks intrigued) What?`,-1),c[463]||=a(`blockquote`,null,[a(`p`,null,`好吧，等等！来吧等一下！一定有我能做的事！某物如果我们还有那个娱乐单元，我会在里面呆上六个小时，想想我是怎么让你失望的。（乔伊看起来很好奇）什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/115.mp3`}),c[464]||=t(` <strong>Joey Tribbiani:</strong> We’ve got a box. (Motions to a large wooden box next to him.)<blockquote><p>我们有一个盒子。（向他旁边的一个大木箱示意。）</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Dr. Burke’s office, Tim is examining Monica.</em></p><blockquote><p>🎬 <em>伯克医生的办公室，蒂姆正在检查莫妮卡。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S04/S04E08/116.mp3`}),c[465]||=i(),c[466]||=a(`strong`,null,`Tim:`,-1),c[467]||=i(` Last time I saw you, it was the morning I left for college. And you were just standing outside The Dairy Queen.`,-1),c[468]||=a(`blockquote`,null,[a(`p`,null,`我上次见到你是在我去上大学的那天早上。而你只是站在奶牛场皇后的外面。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/117.mp3`}),c[469]||=i(),c[470]||=a(`strong`,null,`Monica Geller:`,-1),c[471]||=i(` I was probably waiting for it to open.`,-1),c[472]||=a(`blockquote`,null,[a(`p`,null,`我可能在等它打开。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/118.mp3`}),c[473]||=i(),c[474]||=a(`strong`,null,`Tim:`,-1),c[475]||=i(` I gotta tell you, you look great now.`,-1),c[476]||=a(`blockquote`,null,[a(`p`,null,`我得告诉你，你现在看起来很棒。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/119.mp3`}),c[477]||=i(),c[478]||=a(`strong`,null,`Monica Geller:`,-1),c[479]||=i(` You look great too.`,-1),c[480]||=a(`blockquote`,null,[a(`p`,null,`你看起来也很棒。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/120.mp3`}),c[481]||=i(),c[482]||=a(`strong`,null,`Tim:`,-1),c[483]||=i(` You’re an excellent patient!`,-1),c[484]||=a(`blockquote`,null,[a(`p`,null,`你是个优秀的病人！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/121.mp3`}),c[485]||=i(),c[486]||=a(`strong`,null,`Monica Geller:`,-1),c[487]||=i(` So how does it look?`,-1),c[488]||=a(`blockquote`,null,[a(`p`,null,`看起来怎么样？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/122.mp3`}),c[489]||=i(),c[490]||=a(`strong`,null,`Tim:`,-1),c[491]||=i(` Well, you’ve got a little scratch on your cornea, your gonna have to wear a patch for a couple of days.`,-1),c[492]||=a(`blockquote`,null,[a(`p`,null,`嗯，你的角膜有点划痕，你得戴几天的眼罩。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/123.mp3`}),c[493]||=i(),c[494]||=a(`strong`,null,`Monica Geller:`,-1),c[495]||=i(` Like a pirate?!`,-1),c[496]||=a(`blockquote`,null,[a(`p`,null,`像个海盗？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/124.mp3`}),c[497]||=i(),c[498]||=a(`strong`,null,`Tim:`,-1),c[499]||=i(` If that helps you.`,-1),c[500]||=a(`blockquote`,null,[a(`p`,null,`如果这对你有帮助的话。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/125.mp3`}),c[501]||=i(),c[502]||=a(`strong`,null,`Monica Geller:`,-1),c[503]||=i(` Umm, so how long have you been working with your dad? (He looks at her) Come on, one of us had to mention him.`,-1),c[504]||=a(`blockquote`,null,[a(`p`,null,`嗯，你和你爸爸一起工作多久了？（他看着她）来吧，我们中的一个人不得不提到他。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/126.mp3`}),c[505]||=i(),c[506]||=a(`strong`,null,`Tim:`,-1),c[507]||=i(` I moved back here a couple of months ago.`,-1),c[508]||=a(`blockquote`,null,[a(`p`,null,`我几个月前搬回来的。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/127.mp3`}),c[509]||=i(),c[510]||=a(`strong`,null,`Monica Geller:`,-1),c[511]||=i(` Oh. Big family dinner tonight?`,-1),c[512]||=a(`blockquote`,null,[a(`p`,null,`哦。今晚的家庭大餐？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/128.mp3`}),c[513]||=i(),c[514]||=a(`strong`,null,`Tim:`,-1),c[515]||=i(` Uh. (He holds up a brown lunch bag.)`,-1),c[516]||=a(`blockquote`,null,[a(`p`,null,`嗯。（他举起一个棕色的午餐袋。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/129.mp3`}),c[517]||=i(),c[518]||=a(`strong`,null,`Monica Geller:`,-1),c[519]||=i(` No way!`,-1),c[520]||=a(`blockquote`,null,[a(`p`,null,`不可能！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/130.mp3`}),c[521]||=i(),c[522]||=a(`strong`,null,`Tim:`,-1),c[523]||=i(` I was gonna have Thanksgiving at my girlfriend’s.`,-1),c[524]||=a(`blockquote`,null,[a(`p`,null,`我本来打算在我女朋友家过感恩节的。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/131.mp3`}),c[525]||=i(),c[526]||=a(`strong`,null,`Monica Geller:`,-1),c[527]||=i(` (disappointed) Oh.`,-1),c[528]||=a(`blockquote`,null,[a(`p`,null,`（失望）哦。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/132.mp3`}),c[529]||=i(),c[530]||=a(`strong`,null,`Tim:`,-1),c[531]||=i(` But we broke up.`,-1),c[532]||=a(`blockquote`,null,[a(`p`,null,`但是我们分手了。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/133.mp3`}),c[533]||=i(),c[534]||=a(`strong`,null,`Monica Geller:`,-1),c[535]||=i(` (happy) Oh.`,-1),c[536]||=a(`blockquote`,null,[a(`p`,null,`（高兴）哦。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/134.mp3`}),c[537]||=i(),c[538]||=a(`strong`,null,`Tim:`,-1),c[539]||=i(` She-she wasn’t ready for a serious commitment.`,-1),c[540]||=a(`blockquote`,null,[a(`p`,null,`她还没有准备好认真地承诺。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/135.mp3`}),c[541]||=i(),c[542]||=a(`strong`,null,`Monica Geller:`,-1),c[543]||=i(` (sympathetic) Oh. (in a pirate’s voice) So you made her walk the plank? Aye, matie?`,-1),c[544]||=a(`blockquote`,null,[a(`p`,null,`（同情地）哦。（用海盗的声音）所以你让她走木板？是吗，玛蒂？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/136.mp3`}),c[545]||=i(),c[546]||=a(`strong`,null,`Tim:`,-1),c[547]||=i(` You’re not wearing the patch yet.`,-1),c[548]||=a(`blockquote`,null,[a(`p`,null,`你还没戴补丁呢。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/137.mp3`}),c[549]||=i(),c[550]||=a(`strong`,null,`Monica Geller:`,-1),c[551]||=i(` I know.`,-1),c[552]||=a(`blockquote`,null,[a(`p`,null,`我知道。`)],-1),c[553]||=a(`hr`,null,null,-1),c[554]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, It’s closer to dinner. Monica has just told everyone that Tim is coming to dinner.`)],-1),c[555]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，快吃饭了。莫妮卡刚刚告诉大家蒂姆要来吃饭。`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/138.mp3`}),c[556]||=i(),c[557]||=a(`strong`,null,`Ross Geller:`,-1),c[558]||=i(` He’s coming here for Thanksgiving!`,-1),c[559]||=a(`blockquote`,null,[a(`p`,null,`他要来这里过感恩节！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/139.mp3`}),c[560]||=i(),c[561]||=a(`strong`,null,`Rachel Green:`,-1),c[562]||=i(` I know, it’s sick.`,-1),c[563]||=a(`blockquote`,null,[a(`p`,null,`我知道，它病了。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/140.mp3`}),c[564]||=i(),c[565]||=a(`strong`,null,`Monica Geller:`,-1),c[566]||=i(` Why is it sick?`,-1),c[567]||=a(`blockquote`,null,[a(`p`,null,`为什么病了？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/141.mp3`}),c[568]||=i(),c[569]||=a(`strong`,null,`Rachel Green:`,-1),c[570]||=i(` Because it’s Richard’s son! It’s like inviting Greek tragedy over for dinner!`,-1),c[571]||=a(`blockquote`,null,[a(`p`,null,`因为那是理查德的儿子！这就像邀请希腊悲剧来吃饭一样！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/142.mp3`}),c[572]||=i(),c[573]||=a(`strong`,null,`Monica Geller:`,-1),c[574]||=i(` Hey, come on, Phoebe, you understand don’t you?`,-1),c[575]||=a(`blockquote`,null,[a(`p`,null,`嘿，拜托，菲比，你明白吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/143.mp3`}),c[576]||=i(),c[577]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[578]||=i(` Yeah, I can see where I’d be your best shot but, no. I’m sorry, but I think it’s twisted.`,-1),c[579]||=a(`blockquote`,null,[a(`p`,null,`是的，我知道我会是你最好的选择，但是，不。对不起，但我认为这是扭曲的。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/144.mp3`}),c[580]||=i(),c[581]||=a(`strong`,null,`Ross Geller:`,-1),c[582]||=i(` Yeah.`,-1),c[583]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/145.mp3`}),c[584]||=i(),c[585]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[586]||=i(` (coming out of the bathroom) What’s twisted?`,-1),c[587]||=a(`blockquote`,null,[a(`p`,null,`（从浴室出来）怎么了？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/146.mp3`}),c[588]||=i(),c[589]||=a(`strong`,null,`Monica Geller:`,-1),c[590]||=i(` Me going out with Richard’s son.`,-1),c[591]||=a(`blockquote`,null,[a(`p`,null,`我和理查德的儿子约会。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/147.mp3`}),c[592]||=i(),c[593]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[594]||=i(` Ewwwww!! Ew! Ew! Ew!`,-1),c[595]||=a(`blockquote`,null,[a(`p`,null,`哇！！电子战！电子战！电子战！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/148.mp3`}),c[596]||=i(),c[597]||=a(`strong`,null,`Chandler Bing:`,-1),c[598]||=i(` (He is now in the box, in their living room.) Sounds like a really bad idea to me.`,-1),c[599]||=a(`blockquote`,null,[a(`p`,null,`（他现在在包厢里，在他们的起居室里。）对我来说这听起来真是个坏主意。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/149.mp3`}),c[600]||=i(),c[601]||=a(`strong`,null,`Rachel Green:`,-1),c[602]||=i(` Is he okay in there?`,-1),c[603]||=a(`blockquote`,null,[a(`p`,null,`他在里面还好吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/150.mp3`}),c[604]||=i(),c[605]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[606]||=i(` He’s fine!`,-1),c[607]||=a(`blockquote`,null,[a(`p`,null,`他很好！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/151.mp3`}),c[608]||=i(),c[609]||=a(`strong`,null,`Ross Geller:`,-1),c[610]||=i(` Hey, y'know, Mon, if things wrong out between you and Richard’s son, you’d be able to tell your kids, that you slept with their grandfather.`,-1),c[611]||=a(`blockquote`,null,[a(`p`,null,`嘿，你知道，拜托，如果你和理查德的儿子之间出了问题，你可以告诉你的孩子，你和他们的祖父上过床。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/152.mp3`}),c[612]||=i(),c[613]||=a(`strong`,null,`Monica Geller:`,-1),c[614]||=i(` Fine! Judge all you want to but, (points to Ross) married a lesbian, (points to Rachel) left a man at the altar, (points to Phoebe) fell in love with a gay ice dancer, (points to Joey) threw a girl’s wooden leg in a fire, (points to Chandler) livin’ in a box!! (goes to her room)`,-1),c[615]||=a(`blockquote`,null,[a(`p`,null,`很好！评判你想评判的一切，但是，（指着罗斯）娶了一个女同性恋，（指着瑞秋）把一个男人留在祭坛上，（指着菲比）爱上了一个同性恋冰舞演员，（指着乔伊）把一个女孩的木腿扔到火里，（指着钱德勒）住在盒子里！！（去她的房间）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/153.mp3`}),c[616]||=i(),c[617]||=a(`strong`,null,`Rachel Green:`,-1),c[618]||=i(` So now, what exactly is the point of the box?`,-1),c[619]||=a(`blockquote`,null,[a(`p`,null,`那么，这个盒子到底有什么意义呢？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/154.mp3`}),c[620]||=i(),c[621]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[622]||=i(` Chandler?`,-1),c[623]||=a(`blockquote`,null,[a(`p`,null,`钱德勒？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/155.mp3`}),c[624]||=i(),c[625]||=a(`strong`,null,`Chandler Bing:`,-1),c[626]||=i(` The meaning of the box is three fold. One (holds a finger up through the air hole), it gives me the time to think about what I did. Two (holds up another finger), it proves how much I care about my friendship with Joey. And three (holds up a third finger), it hurts!`,-1),c[627]||=a(`blockquote`,null,[a(`p`,null,`这个盒子有三层含义。一个（通过气孔举起一根手指），它让我有时间思考我做了什么。第二个（举起另一个手指），它证明了我是多么在乎我和乔伊的友谊。第三个（举起第三个手指），很疼！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/156.mp3`}),c[628]||=i(),c[629]||=a(`strong`,null,`Ross Geller:`,-1),c[630]||=i(` (to Rachel) Oh hey! Hey uh, you remember the necklace I gave you last year? Can I see it?`,-1),c[631]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）哦，嘿！还记得我去年给你的项链吗？我能看看吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/157.mp3`}),c[632]||=i(),c[633]||=a(`strong`,null,`Rachel Green:`,-1),c[634]||=i(` (worried) Why?`,-1),c[635]||=a(`blockquote`,null,[a(`p`,null,`（担心）为什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/158.mp3`}),c[636]||=i(),c[637]||=a(`strong`,null,`Ross Geller:`,-1),c[638]||=i(` I just wanna check something.`,-1),c[639]||=a(`blockquote`,null,[a(`p`,null,`我只是想看看。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/159.mp3`}),c[640]||=i(),c[641]||=a(`strong`,null,`Rachel Green:`,-1),c[642]||=i(` Okay. (She goes into her bedroom)`,-1),c[643]||=a(`blockquote`,null,[a(`p`,null,`好的。（她走进卧室）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/160.mp3`}),c[644]||=i(),c[645]||=a(`strong`,null,`Ross Geller:`,-1),c[646]||=i(` (He puts his hand over the hole on the box.) (to Chandler) Now, we’ll see.`,-1),c[647]||=a(`blockquote`,null,[a(`p`,null,`（他把手放在盒子上的洞上。）（对钱德勒）现在，我们看看。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/161.mp3`}),c[648]||=i(),c[649]||=a(`strong`,null,`Chandler Bing:`,-1),c[650]||=i(` Air hole! Air hole!! (Ross retracts his hand quickly.)`,-1),c[651]||=a(`blockquote`,null,[a(`p`,null,`气孔！气孔！！（罗斯迅速缩回他的手。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/162.mp3`}),c[652]||=i(),c[653]||=a(`strong`,null,`Rachel Green:`,-1),c[654]||=i(` (coming out of her bedroom with a necklace) Here it is! I love it. I wear it all the time.`,-1),c[655]||=a(`blockquote`,null,[a(`p`,null,`（拿着项链走出卧室）给你！我喜欢它。我一直戴着它。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/163.mp3`}),c[656]||=i(),c[657]||=a(`strong`,null,`Ross Geller:`,-1),c[658]||=i(` (grabbing the necklace) The necklace I got you was gold, this one is silver.`,-1),c[659]||=a(`blockquote`,null,[a(`p`,null,`（抓住项链）我给你的项链是金的，这条是银的。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/164.mp3`}),c[660]||=i(),c[661]||=a(`strong`,null,`Rachel Green:`,-1),c[662]||=i(` Huh, well maybe it uh, it changed.`,-1),c[663]||=a(`blockquote`,null,[a(`p`,null,`嗯，嗯，也许它，呃，它变了。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/165.mp3`}),c[664]||=i(),c[665]||=a(`strong`,null,`Ross Geller:`,-1),c[666]||=i(` Oh my God! You actually exchanged it!`,-1),c[667]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！你真的换了！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/166.mp3`}),c[668]||=i(),c[669]||=a(`strong`,null,`Rachel Green:`,-1),c[670]||=i(` Well isn’t it better that I exchanged it for something that I enjoy and that I can get a lot of use out of?`,-1),c[671]||=a(`blockquote`,null,[a(`p`,null,`嗯，我把它换成我喜欢的东西，而且我可以从中得到很多好处，不是更好吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/167.mp3`}),c[672]||=i(),c[673]||=a(`strong`,null,`Ross Geller:`,-1),c[674]||=i(` What did you get?`,-1),c[675]||=a(`blockquote`,null,[a(`p`,null,`你得到了什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/168.mp3`}),c[676]||=i(),c[677]||=a(`strong`,null,`Rachel Green:`,-1),c[678]||=i(` Credit.`,-1),c[679]||=a(`blockquote`,null,[a(`p`,null,`信用卡。`)],-1),c[680]||=a(`p`,null,[a(`em`,null,`(There’s a knock on the door.)`)],-1),c[681]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（有人敲门。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/169.mp3`}),c[682]||=i(),c[683]||=a(`strong`,null,`Monica Geller:`,-1),c[684]||=i(` (running in from her bedroom) I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! I’ll get it! (opens the door) Hi, Tim.`,-1),c[685]||=a(`blockquote`,null,[a(`p`,null,`（从卧室跑进来）我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！我去拿！（开门）嗨，蒂姆。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/170.mp3`}),c[686]||=i(),c[687]||=a(`strong`,null,`Tim:`,-1),c[688]||=i(` Hi. (gives her a bottle of wine)`,-1),c[689]||=a(`blockquote`,null,[a(`p`,null,`嗨。（给她一瓶酒）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/171.mp3`}),c[690]||=i(),c[691]||=a(`strong`,null,`Monica Geller:`,-1),c[692]||=i(` Thank you. Come meet my friends. This is uh, Phoebe.`,-1),c[693]||=a(`blockquote`,null,[a(`p`,null,`谢谢。来见见我的朋友。这是菲比。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/172.mp3`}),c[694]||=i(),c[695]||=a(`strong`,null,`Tim:`,-1),c[696]||=i(` Hi, nice to meet you.`,-1),c[697]||=a(`blockquote`,null,[a(`p`,null,`嗨，很高兴认识你。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/173.mp3`}),c[698]||=i(),c[699]||=a(`strong`,null,`Monica Geller:`,-1),c[700]||=i(` And Joey.`,-1),c[701]||=a(`blockquote`,null,[a(`p`,null,`还有乔伊。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/174.mp3`}),c[702]||=i(),c[703]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[704]||=i(` Hey!`,-1),c[705]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/175.mp3`}),c[706]||=i(),c[707]||=a(`strong`,null,`Tim:`,-1),c[708]||=i(` Hi, Joey.`,-1),c[709]||=a(`blockquote`,null,[a(`p`,null,`嗨，乔伊。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/176.mp3`}),c[710]||=i(),c[711]||=a(`strong`,null,`Monica Geller:`,-1),c[712]||=i(` My brother, Ross.`,-1),c[713]||=a(`blockquote`,null,[a(`p`,null,`我哥哥，罗斯。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/177.mp3`}),c[714]||=i(),c[715]||=a(`strong`,null,`Ross Geller:`,-1),c[716]||=i(` Hey.`,-1),c[717]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/178.mp3`}),c[718]||=i(),c[719]||=a(`strong`,null,`Monica Geller:`,-1),c[720]||=i(` And Rachel. (Chandler clears his voice loudly) And that’s Chandler.`,-1),c[721]||=a(`blockquote`,null,[a(`p`,null,`还有瑞秋。（钱德勒大声清了清嗓子）那就是钱德勒。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/179.mp3`}),c[722]||=i(),c[723]||=a(`strong`,null,`Chandler Bing:`,-1),c[724]||=i(` How do ya do.`,-1),c[725]||=a(`blockquote`,null,[a(`p`,null,`你好。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/180.mp3`}),c[726]||=i(),c[727]||=a(`strong`,null,`Tim:`,-1),c[728]||=i(` What’s…`,-1),c[729]||=a(`blockquote`,null,[a(`p`,null,`什么是…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/181.mp3`}),c[730]||=i(),c[731]||=a(`strong`,null,`Monica Geller:`,-1),c[732]||=i(` Umm, well, he’s…`,-1),c[733]||=a(`blockquote`,null,[a(`p`,null,`嗯，他…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/182.mp3`}),c[734]||=i(),c[735]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[736]||=i(` He’s doin’ some thinkin’!`,-1),c[737]||=a(`blockquote`,null,[a(`p`,null,`他在思考！`)],-1),c[738]||=a(`p`,null,`[cut to later, Joey, Rachel, Ross, and Tim are watching the football game, and they all cheer loudly.]`,-1),c[739]||=a(`blockquote`,null,[a(`p`,null,`[切到稍后，乔伊、瑞秋、罗斯和蒂姆正在看足球比赛，他们都大声欢呼。]`)],-1),r(p,{src:`/audio/friends/S04/S04E08/183.mp3`}),c[740]||=i(),c[741]||=a(`strong`,null,`Chandler Bing:`,-1),c[742]||=i(` What happened? What happened?!`,-1),c[743]||=a(`blockquote`,null,[a(`p`,null,`发生什么事了？发生什么事了？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/184.mp3`}),c[744]||=i(),c[745]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[746]||=i(` You kissed my girlfriend!`,-1),c[747]||=a(`blockquote`,null,[a(`p`,null,`你吻了我女朋友！`)],-1),c[748]||=a(`p`,null,[a(`em`,null,`(A commercial for sunglasses comes on.)`)],-1),c[749]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（太阳镜广告上映。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/185.mp3`}),c[750]||=i(),c[751]||=a(`strong`,null,`Rachel Green:`,-1),c[752]||=i(` Ooh, I like those sunglasses.`,-1),c[753]||=a(`blockquote`,null,[a(`p`,null,`哦，我喜欢那些太阳镜。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/186.mp3`}),c[754]||=i(),c[755]||=a(`strong`,null,`Ross Geller:`,-1),c[756]||=i(` Like ‘em, like ‘em? Or, I’d like to get store credit for that amount like ‘em?`,-1),c[757]||=a(`blockquote`,null,[a(`p`,null,`喜欢他们，喜欢他们？或者，我想像他们一样得到商店的信用？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/187.mp3`}),c[758]||=i(),c[759]||=a(`strong`,null,`Rachel Green:`,-1),c[760]||=i(` (Swears in Italian, it’s the same term used by Joey earlier and Joey nods his approval.)`,-1),c[761]||=a(`blockquote`,null,[a(`p`,null,`（用意大利语发誓，这是乔伊早些时候用的同一个词，乔伊点头表示赞同。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/188.mp3`}),c[762]||=i(),c[763]||=a(`strong`,null,`Monica Geller:`,-1),c[764]||=i(` All right everybody, this turkey is ready!`,-1),c[765]||=a(`blockquote`,null,[a(`p`,null,`好了，各位，火鸡准备好了！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/189.mp3`}),c[766]||=i(),c[767]||=a(`strong`,null,`Tim:`,-1),c[768]||=i(` Where can I wash up?`,-1),c[769]||=a(`blockquote`,null,[a(`p`,null,`我在哪里可以洗碗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/190.mp3`}),c[770]||=i(),c[771]||=a(`strong`,null,`Monica Geller:`,-1),c[772]||=i(` Here, let me show you. Okay, the towels are hanging next to the sink, and umm, you can use the fancy soap.`,-1),c[773]||=a(`blockquote`,null,[a(`p`,null,`来，让我给你看看。好的，毛巾挂在水槽旁边，嗯，你可以用这种奇特的肥皂。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/191.mp3`}),c[774]||=i(),c[775]||=a(`strong`,null,`Tim:`,-1),c[776]||=i(` Thank you.`,-1),c[777]||=a(`blockquote`,null,[a(`p`,null,`谢谢。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/192.mp3`}),c[778]||=i(),c[779]||=a(`strong`,null,`Rachel Green:`,-1),c[780]||=i(` Fancy soap? I thought we were savin’ that for the Pope!`,-1),c[781]||=a(`blockquote`,null,[a(`p`,null,`喜欢肥皂吗？我以为我们是为了教皇才这么做的！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/193.mp3`}),c[782]||=i(),c[783]||=a(`strong`,null,`Monica Geller:`,-1),c[784]||=i(` See he’s nice. Right?`,-1),c[785]||=a(`blockquote`,null,[a(`p`,null,`看，他很好。对吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/194.mp3`}),c[786]||=i(),c[787]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[788]||=i(` Yeah, but Monica, do you actually want to be in a relationship where you can actually use the phrase, "That’s not how your dad used to do it."`,-1),c[789]||=a(`blockquote`,null,[a(`p`,null,`是的，但是莫妮卡，你真的想在一段感情中，你真的可以用“你爸爸以前不是这样做的”这句话吗`)],-1),r(p,{src:`/audio/friends/S04/S04E08/195.mp3`}),c[790]||=i(),c[791]||=a(`strong`,null,`Tim:`,-1),c[792]||=i(` Wow! Everything looks great! Where should I sit?`,-1),c[793]||=a(`blockquote`,null,[a(`p`,null,`哇！一切看起来都很棒！我应该坐在哪里？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/196.mp3`}),c[794]||=i(),c[795]||=a(`strong`,null,`Monica Geller:`,-1),c[796]||=i(` I saved you a seat. (Motions to the one next to her.)`,-1),c[797]||=a(`blockquote`,null,[a(`p`,null,`我给你留了个座位。（向她旁边的人示意。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/197.mp3`}),c[798]||=i(),c[799]||=a(`strong`,null,`Rachel Green:`,-1),c[800]||=i(` (pouring the wine) Sick-sick-sick-sick.`,-1),c[801]||=a(`blockquote`,null,[a(`p`,null,`（倒酒）病了。`)],-1),c[802]||=a(`p`,null,[a(`em`,null,`(There’s a loud knocking.)`)],-1),c[803]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（有一声巨响。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/198.mp3`}),c[804]||=i(),c[805]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[806]||=i(` Oh, I’ll get it. (goes over to the door.)`,-1),c[807]||=a(`blockquote`,null,[a(`p`,null,`哦，我去拿。（走到门口。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/199.mp3`}),c[808]||=i(),c[809]||=a(`strong`,null,`Chandler Bing:`,-1),c[810]||=i(` Gotcha! (laughs)`,-1),c[811]||=a(`blockquote`,null,[a(`p`,null,`明白了！（笑）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/200.mp3`}),c[812]||=i(),c[813]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[814]||=i(` That doesn’t sound like thinking to me!`,-1),c[815]||=a(`blockquote`,null,[a(`p`,null,`我听起来不像在想什么！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/201.mp3`}),c[816]||=i(),c[817]||=a(`strong`,null,`Chandler Bing:`,-1),c[818]||=i(` Sorry!`,-1),c[819]||=a(`blockquote`,null,[a(`p`,null,`对不起！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/202.mp3`}),c[820]||=i(),c[821]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[822]||=i(` Y’know I don’t think you should be talking at all in there! I think you’ve got to much thinking to do to be talking and making jokes!`,-1),c[823]||=a(`blockquote`,null,[a(`p`,null,`你知道我觉得你根本不应该在里面说话！我想你要想说话和开玩笑，还得多想！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/203.mp3`}),c[824]||=i(),c[825]||=a(`strong`,null,`Chandler Bing:`,-1),c[826]||=i(` Okay, okay, you got it!`,-1),c[827]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，你明白了！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/204.mp3`}),c[828]||=i(),c[829]||=a(`strong`,null,`Rachel Green:`,-1),c[830]||=i(` Ross, can you pass me the yams?`,-1),c[831]||=a(`blockquote`,null,[a(`p`,null,`罗斯，你能把山药递给我吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/205.mp3`}),c[832]||=i(),c[833]||=a(`strong`,null,`Ross Geller:`,-1),c[834]||=i(` Sure! Oh, and Joey’s got the mashed potatoes if you want to exchange them.`,-1),c[835]||=a(`blockquote`,null,[a(`p`,null,`当然！哦，如果你想换土豆泥，乔伊有土豆泥。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/206.mp3`}),c[836]||=i(),c[837]||=a(`strong`,null,`Rachel Green:`,-1),c[838]||=i(` Would you stop?! What is the matter with you?!`,-1),c[839]||=a(`blockquote`,null,[a(`p`,null,`你能停下来吗？！你怎么了？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/207.mp3`}),c[840]||=i(),c[841]||=a(`strong`,null,`Monica Geller:`,-1),c[842]||=i(` Oh-ho-ho, we’ve got company.`,-1),c[843]||=a(`blockquote`,null,[a(`p`,null,`哦，呵呵，我们有客人。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/208.mp3`}),c[844]||=i(),c[845]||=a(`strong`,null,`Ross Geller:`,-1),c[846]||=i(` There’s nothing the matter with me. See, I’m not completely devoid of sentiment, see I have feelings.`,-1),c[847]||=a(`blockquote`,null,[a(`p`,null,`我没什么问题。看，我不是完全没有感情，看，我有感情。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/209.mp3`}),c[848]||=i(),c[849]||=a(`strong`,null,`Rachel Green:`,-1),c[850]||=i(` Okay, fine. (She gets up and walks into her bedroom)`,-1),c[851]||=a(`blockquote`,null,[a(`p`,null,`好的，很好。（她站起来走进卧室）`)],-1),c[852]||=a(`p`,null,[a(`em`,null,`(an awkward silence follows)`)],-1),c[853]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（接着是尴尬的沉默）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/210.mp3`}),c[854]||=i(),c[855]||=a(`strong`,null,`Chandler Bing:`,-1),c[856]||=i(` You can’t tell, but I’m trying to break the tension by mooning you guys!`,-1),c[857]||=a(`blockquote`,null,[a(`p`,null,`你说不出来，但我想通过和你们鬼混来打破紧张气氛！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/211.mp3`}),c[858]||=i(),c[859]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[860]||=i(` All right, look! If this is just a big joke to you, then forget about it, all right?! This means something to me! And if it doesn’t mean anything to you, then you should get out of there, otherwise you’re just an idiot in a box!`,-1),c[861]||=a(`blockquote`,null,[a(`p`,null,`好吧，看！如果这对你来说只是个大笑话，那就忘了它，好吗？！这对我来说意义重大！如果这对你没有任何意义，那么你应该离开那里，否则你只是一个盒子里的白痴！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/212.mp3`}),c[862]||=i(),c[863]||=a(`strong`,null,`Chandler Bing:`,-1),c[864]||=i(` You’re right, and I’m sorry! This means a lot to me! I want you to be my friend again! I swear, I won’t say another word tonight.`,-1),c[865]||=a(`blockquote`,null,[a(`p`,null,`你说得对，我很抱歉！这对我来说意义重大！我希望你再次成为我的朋友！我发誓，今晚我一句话也不说。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/213.mp3`}),c[866]||=i(),c[867]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[868]||=i(` So are you gonna start taking this thing seriously?`,-1),c[869]||=a(`blockquote`,null,[a(`p`,null,`那你要开始认真对待这件事了吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/214.mp3`}),c[870]||=i(),c[871]||=a(`strong`,null,`Chandler Bing:`,-1),c[872]||=i(` Absolutely!`,-1),c[873]||=a(`blockquote`,null,[a(`p`,null,`当然！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/215.mp3`}),c[874]||=i(),c[875]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[876]||=i(` That sounds like another word to me! Are you gonna take this seriously? (There’s no response from Chandler.) Okay.`,-1),c[877]||=a(`blockquote`,null,[a(`p`,null,`对我来说，这听起来像是另一个词！你会认真对待这件事吗？（钱德勒没有回应）好的。`)],-1),c[878]||=a(`p`,null,[a(`em`,null,`(Rachel comes back carrying a shoe box.)`)],-1),c[879]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋拿着一个鞋盒回来了。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/216.mp3`}),c[880]||=i(),c[881]||=a(`strong`,null,`Rachel Green:`,-1),c[882]||=i(` Don’t say that I have no sentiment! (Starts to show Ross what’s in the box.) This is a movie stub from our first date! This is an eggshell from the first time you made me breakfast in bed! (Holds up a bone) This is from the museum from the first time we… were together. Okay, maybe I exchange gifts sometimes, but I keep the things that matter!`,-1),c[883]||=a(`blockquote`,null,[a(`p`,null,`别说我没有感情！（开始向罗斯展示盒子里的东西。）这是我们第一次约会的电影存根！这是你第一次在床上给我做早餐时的蛋壳！（举着一根骨头）这是我们第一次在一起时从博物馆拿来的。好吧，也许我有时会交换礼物，但我会保留重要的东西！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/217.mp3`}),c[884]||=i(),c[885]||=a(`strong`,null,`Ross Geller:`,-1),c[886]||=i(` I don’t know what to say, I’m sorry. Though, you’re not supposed to take these. (Points to the bone) It’s like a million years old, we, we actually, we had people looking for that.`,-1),c[887]||=a(`blockquote`,null,[a(`p`,null,`我不知道该说什么，对不起。不过，你不应该拿这些。（指着骨头）它好像有一百万年了，我们，我们实际上，我们有人在找它。`)],-1),c[888]||=a(`p`,null,[a(`em`,null,`(Rachel glares at him.)`)],-1),c[889]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋瞪了他一眼。）`)])],-1),c[890]||=a(`p`,null,`[Cut to the balcony with Monica and Tim.]`,-1),c[891]||=a(`blockquote`,null,[a(`p`,null,`[与莫妮卡和蒂姆一起切到阳台上。]`)],-1),r(p,{src:`/audio/friends/S04/S04E08/218.mp3`}),c[892]||=i(),c[893]||=a(`strong`,null,`Monica Geller:`,-1),c[894]||=i(` (putting off her coat) Ooh, this always happens. (Her coat gets stuck.)`,-1),c[895]||=a(`blockquote`,null,[a(`p`,null,`（脱下外套）哦，这种事经常发生。（她的外套卡住了。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/219.mp3`}),c[896]||=i(),c[897]||=a(`strong`,null,`Tim:`,-1),c[898]||=i(` Here, let me help. (Does so.)`,-1),c[899]||=a(`blockquote`,null,[a(`p`,null,`来，让我帮忙。（确实如此。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/220.mp3`}),c[900]||=i(),c[901]||=a(`strong`,null,`Monica Geller:`,-1),c[902]||=i(` Thank you.`,-1),c[903]||=a(`blockquote`,null,[a(`p`,null,`谢谢。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/221.mp3`}),c[904]||=i(),c[905]||=a(`strong`,null,`Tim:`,-1),c[906]||=i(` You-you have a very beautiful… eye.`,-1),c[907]||=a(`blockquote`,null,[a(`p`,null,`你有一双非常美丽的眼睛。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/222.mp3`}),c[908]||=i(),c[909]||=a(`strong`,null,`Monica Geller:`,-1),c[910]||=i(` Y’know all my friends think this is weird.`,-1),c[911]||=a(`blockquote`,null,[a(`p`,null,`你知道我所有的朋友都觉得这很奇怪。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/223.mp3`}),c[912]||=i(),c[913]||=a(`strong`,null,`Tim:`,-1),c[914]||=i(` Y’know I-I thought it was gonna be weird, I mean I almost called and canceled, but it really isn’t.`,-1),c[915]||=a(`blockquote`,null,[a(`p`,null,`你知道，我觉得会很奇怪，我是说我差点打电话取消了，但事实并非如此。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/224.mp3`}),c[916]||=i(),c[917]||=a(`strong`,null,`Monica Geller:`,-1),c[918]||=i(` I know! I mean it’s like me and your dad, that’s a totally separate thing.`,-1),c[919]||=a(`blockquote`,null,[a(`p`,null,`我知道！我是说，就像我和你爸爸一样，这是完全不同的事情。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/225.mp3`}),c[920]||=i(),c[921]||=a(`strong`,null,`Tim:`,-1),c[922]||=i(` Oh, I totally agree.`,-1),c[923]||=a(`blockquote`,null,[a(`p`,null,`哦，我完全同意。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/226.mp3`}),c[924]||=i(),c[925]||=a(`strong`,null,`Monica Geller:`,-1),c[926]||=i(` We’re just two people who find each other very attractive. Right?`,-1),c[927]||=a(`blockquote`,null,[a(`p`,null,`我们只是两个觉得对方很有吸引力的人。对吗？`)],-1),c[928]||=a(`p`,null,[a(`em`,null,`(Tim leans in to kiss her. They stop, and when he tries to kiss her again, Monica pulls away.)`)],-1),c[929]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（蒂姆俯身吻她。他们停了下来，当他再次试图吻她时，莫妮卡拉开了手。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/227.mp3`}),c[930]||=i(),c[931]||=a(`strong`,null,`Tim:`,-1),c[932]||=i(` What?`,-1),c[933]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/228.mp3`}),c[934]||=i(),c[935]||=a(`strong`,null,`Monica Geller:`,-1),c[936]||=i(` Nothing. Nothing.`,-1),c[937]||=a(`blockquote`,null,[a(`p`,null,`没什么。没有什么。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/229.mp3`}),c[938]||=i(),c[939]||=a(`strong`,null,`Tim:`,-1),c[940]||=i(` No-no really, was-was that not okay?`,-1),c[941]||=a(`blockquote`,null,[a(`p`,null,`不，不，真的，这样不好吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/230.mp3`}),c[942]||=i(),c[943]||=a(`strong`,null,`Monica Geller:`,-1),c[944]||=i(` No-no-no that was good, it was, that was uh, that was a goood kiss…`,-1),c[945]||=a(`blockquote`,null,[a(`p`,null,`不，不，那很好，那是，那是，呃，那是一个很好的吻…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/231.mp3`}),c[946]||=i(),c[947]||=a(`strong`,null,`Tim:`,-1),c[948]||=i(` Oh my God! It didn’t remind you of…`,-1),c[949]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！它没有让你想起…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/232.mp3`}),c[950]||=i(),c[951]||=a(`strong`,null,`Monica Geller:`,-1),c[952]||=i(` (interrupting) Don’t say it!`,-1),c[953]||=a(`blockquote`,null,[a(`p`,null,`（打断）别说了！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/233.mp3`}),c[954]||=i(),c[955]||=a(`strong`,null,`Tim:`,-1),c[956]||=i(` No, but it did! Didn’t it?!`,-1),c[957]||=a(`blockquote`,null,[a(`p`,null,`没有，但它做到了！不是吗？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/234.mp3`}),c[958]||=i(),c[959]||=a(`strong`,null,`Monica Geller:`,-1),c[960]||=i(` Yeah!`,-1),c[961]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/235.mp3`}),c[962]||=i(),c[963]||=a(`strong`,null,`Tim:`,-1),c[964]||=i(` Oh man!!`,-1),c[965]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪！！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/236.mp3`}),c[966]||=i(),c[967]||=a(`strong`,null,`Monica Geller:`,-1),c[968]||=i(` I know!`,-1),c[969]||=a(`blockquote`,null,[a(`p`,null,`我知道！`)],-1),c[970]||=a(`p`,null,[a(`em`,null,`(They both shiver in horror.)`)],-1),c[971]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们都吓得发抖。）`)])],-1),c[972]||=a(`p`,null,`[cut to later, Tim has left. Monica is still shivering. There’s a knock on the door.]`,-1),c[973]||=a(`blockquote`,null,[a(`p`,null,`[切到稍后，蒂姆已经走了。莫妮卡还在发抖。有人敲门。]`)],-1),r(p,{src:`/audio/friends/S04/S04E08/237.mp3`}),c[974]||=i(),c[975]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[976]||=i(` I’ll get it. (It’s Kathy.)`,-1),c[977]||=a(`blockquote`,null,[a(`p`,null,`我去拿。（我是凯西。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/238.mp3`}),c[978]||=i(),c[979]||=a(`strong`,null,`Kathy:`,-1),c[980]||=i(` (sees it’s Joey) Oh.`,-1),c[981]||=a(`blockquote`,null,[a(`p`,null,`（看到是乔伊）哦。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/239.mp3`}),c[982]||=i(),c[983]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[984]||=i(` Hey.`,-1),c[985]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/240.mp3`}),c[986]||=i(),c[987]||=a(`strong`,null,`Kathy:`,-1),c[988]||=i(` Hey. Listen, I want you to know how sorry I am…`,-1),c[989]||=a(`blockquote`,null,[a(`p`,null,`嘿。听着，我想让你知道我有多抱歉…`)],-1),r(p,{src:`/audio/friends/S04/S04E08/241.mp3`}),c[990]||=i(),c[991]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[992]||=i(` That’s okay. Chandler’s the one I’m mad at.`,-1),c[993]||=a(`blockquote`,null,[a(`p`,null,`没关系。钱德勒是我最生气的人。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/242.mp3`}),c[994]||=i(),c[995]||=a(`strong`,null,`Kathy:`,-1),c[996]||=i(` Well, I’m still sorry. Is he here?`,-1),c[997]||=a(`blockquote`,null,[a(`p`,null,`嗯，我还是很抱歉。他在吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/243.mp3`}),c[998]||=i(),c[999]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1e3]||=i(` In the box.`,-1),c[1001]||=a(`blockquote`,null,[a(`p`,null,`在盒子里。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/244.mp3`}),c[1002]||=i(),c[1003]||=a(`strong`,null,`Kathy:`,-1),c[1004]||=i(` (going over to the box) Chandler?`,-1),c[1005]||=a(`blockquote`,null,[a(`p`,null,`（走向包厢）钱德勒？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/245.mp3`}),c[1006]||=i(),c[1007]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1008]||=i(` Oh, he-he can’t talk right now.`,-1),c[1009]||=a(`blockquote`,null,[a(`p`,null,`哦，他现在不能说话。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/246.mp3`}),c[1010]||=i(),c[1011]||=a(`strong`,null,`Kathy:`,-1),c[1012]||=i(` Why not? What’s going on?`,-1),c[1013]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？发生什么事？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/247.mp3`}),c[1014]||=i(),c[1015]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1016]||=i(` He’s just trying to show Joey how much he means to him.`,-1),c[1017]||=a(`blockquote`,null,[a(`p`,null,`他只是想让乔伊知道他对他有多重要。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/248.mp3`}),c[1018]||=i(),c[1019]||=a(`strong`,null,`Kathy:`,-1),c[1020]||=i(` By being in a box?`,-1),c[1021]||=a(`blockquote`,null,[a(`p`,null,`被关在盒子里？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/249.mp3`}),c[1022]||=i(),c[1023]||=a(`strong`,null,`Rachel Green:`,-1),c[1024]||=i(` Joey, had reasons.`,-1),c[1025]||=a(`blockquote`,null,[a(`p`,null,`乔伊，我有理由。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/250.mp3`}),c[1026]||=i(),c[1027]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1028]||=i(` They were threefold.`,-1),c[1029]||=a(`blockquote`,null,[a(`p`,null,`有三个。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/251.mp3`}),c[1030]||=i(),c[1031]||=a(`strong`,null,`Kathy:`,-1),c[1032]||=i(` Oh. Well uh, (to Chandler) you not being able to talk may make this easier. Listen umm… (She looks at the gang who are watching, they take the hint and leave them alone.) Listen I don’t wanna be someone who comes between two best friends. I just, I can’t stand seeing what this is doing to you guys, and I don’t wanna be the cause of that. So, I don’t think we can see each other anymore. I’m gonna go to my mom’s in Chicago, I’m gonna stay there for awhile. I think this could’ve be something really amazing, but y’know this is probably for the best. Y’know? I’m gonna miss you. Good-bye, Chandler.`,-1),c[1033]||=a(`blockquote`,null,[a(`p`,null,`哦。嗯，（对钱德勒）你不能说话可能会让这更容易。听着，嗯…（她看着正在观看的那帮人，他们接受了暗示，别管他们。）听着，我不想成为一个夹在两个最好朋友之间的人。我只是，我无法忍受这对你们的影响，我不想成为原因。所以，我想我们再也见不到对方了。我要去芝加哥我妈妈家，我要在那里呆一会儿。我认为这可能是一件非常了不起的事情，但你知道这可能是最好的。你知道吗？我会想你的。再见，钱德勒。`)],-1),c[1034]||=a(`p`,null,[a(`em`,null,`(She gets up and leaves, Chandler waves good-bye with one finger extended through the air hole. Ross glares at Joey.)`)],-1),c[1035]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她起身离开，钱德勒挥手告别，一根手指伸进气孔。罗斯瞪着乔伊。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/252.mp3`}),c[1036]||=i(),c[1037]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1038]||=i(` (starting to cry) Open the box!! (Runs over to do so.)`,-1),c[1039]||=a(`blockquote`,null,[a(`p`,null,`（开始哭）打开盒子！！（跑过去这么做。）`)],-1),r(p,{src:`/audio/friends/S04/S04E08/253.mp3`}),c[1040]||=i(),c[1041]||=a(`strong`,null,`Rachel Green:`,-1),c[1042]||=i(` What?!`,-1),c[1043]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/254.mp3`}),c[1044]||=i(),c[1045]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1046]||=i(` He can still catch her! Come on, get out of there! (He opens the box) Get out of there!`,-1),c[1047]||=a(`blockquote`,null,[a(`p`,null,`他仍然可以抓住她！快点，离开那里！（他打开盒子）滚出去！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/255.mp3`}),c[1048]||=i(),c[1049]||=a(`strong`,null,`Chandler Bing:`,-1),c[1050]||=i(` So?`,-1),c[1051]||=a(`blockquote`,null,[a(`p`,null,`那么？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/256.mp3`}),c[1052]||=i(),c[1053]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1054]||=i(` Yeah, we’re gonna be fine! Get out!`,-1),c[1055]||=a(`blockquote`,null,[a(`p`,null,`是的，我们会没事的！走出！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/257.mp3`}),c[1056]||=i(),c[1057]||=a(`strong`,null,`Chandler Bing:`,-1),c[1058]||=i(` Yeah?`,-1),c[1059]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E08/258.mp3`}),c[1060]||=i(),c[1061]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1062]||=i(` Yeah, you did some real good thinkin’ in there.`,-1),c[1063]||=a(`blockquote`,null,[a(`p`,null,`是的，你在那里做了一些很好的思考。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/259.mp3`}),c[1064]||=i(),c[1065]||=a(`strong`,null,`Chandler Bing:`,-1),c[1066]||=i(` Man, this is…`,-1),c[1067]||=a(`blockquote`,null,[a(`p`,null,`老兄，这是…`)],-1),c[1068]||=a(`p`,null,[a(`em`,null,`(Joey says something unintelligible and they hug.)`)],-1),c[1069]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊说了些莫名其妙的话，他们拥抱了。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/260.mp3`}),c[1070]||=i(),c[1071]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1072]||=i(` Now go! ‘Cause you can still catch her! And Merry Christmas from you’re secret Santa! (Chandler runs out and closes the door.)`,-1),c[1073]||=a(`blockquote`,null,[a(`p`,null,`现在走因为你还能抓住她！祝你圣诞快乐，你是秘密圣诞老人！（钱德勒跑出去，关上门。）`)],-1),c[1074]||=a(`p`,null,[a(`em`,null,`(After he’s gone.)`)],-1),c[1075]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他走后）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/261.mp3`}),c[1076]||=t(` <strong>Joey Tribbiani:</strong> All right, who got Chandler? ‘Cause I uh, need to trade.<blockquote><p>好吧，谁得到钱德勒了？”因为我需要交易。</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s Balcony, the gang is all there watching Chandler.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的阳台，一群人都在那里看着钱德勒。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S04/S04E08/262.mp3`}),c[1077]||=i(),c[1078]||=a(`strong`,null,`Rachel Green:`,-1),c[1079]||=i(` Oh, he sees her!`,-1),c[1080]||=a(`blockquote`,null,[a(`p`,null,`哦，他看见她了！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/263.mp3`}),c[1081]||=i(),c[1082]||=a(`strong`,null,`Monica Geller:`,-1),c[1083]||=i(` Oh, he’s catching up to her!`,-1),c[1084]||=a(`blockquote`,null,[a(`p`,null,`哦，他在追她！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/264.mp3`}),c[1085]||=i(),c[1086]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1087]||=i(` Oh, she sees him! Oh, they’re hugging!`,-1),c[1088]||=a(`blockquote`,null,[a(`p`,null,`哦，她看见他了！哦，他们在拥抱！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/265.mp3`}),c[1089]||=i(),c[1090]||=a(`strong`,null,`Ross Geller:`,-1),c[1091]||=i(` He’s taking her purse!`,-1),c[1092]||=a(`blockquote`,null,[a(`p`,null,`他拿了她的钱包！`)],-1),r(p,{src:`/audio/friends/S04/S04E08/266.mp3`}),c[1093]||=i(),c[1094]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1095]||=i(` Uhh, that’s not them. I’m gonna go call the police.`,-1),c[1096]||=a(`blockquote`,null,[a(`p`,null,`哦，那不是他们。我要去叫警察了。`)],-1),r(p,{src:`/audio/friends/S04/S04E08/267.mp3`}),c[1097]||=i(),c[1098]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1099]||=i(` Oh, there they are!`,-1),c[1100]||=a(`blockquote`,null,[a(`p`,null,`哦，他们在那儿！`)],-1),c[1101]||=a(`p`,null,[a(`em`,null,`(They watch them making up and sigh)`)],-1),c[1102]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们看着他们化妆，叹了口气）`)])],-1),r(p,{src:`/audio/friends/S04/S04E08/268.mp3`}),c[1103]||=i(),c[1104]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1105]||=i(` All right, get a room.`,-1),c[1106]||=a(`blockquote`,null,[a(`p`,null,`好吧，找个房间。`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};